window.SAT_QUESTIONS={"version":1,"metadata":{"notes":"Original Azaman-authored practice bank. No College Board questions or answer keys.","counts":{"rw1":27,"rw2_easy":27,"rw2_hard":27,"math1":22,"math2_easy":22,"math2_hard":22}},"rw1":[{"id":"RWM1Q1","section":"Reading and Writing","domain":"Information and Ideas","skill":"Central ideas","difficulty":"easy","prompt":"Which choice best states the main idea of the text?","options":["The garden served practical and social purposes.","The garden replaced every grocery store in the neighborhood.","Residents preferred the unused lot to the garden.","The garden produced more food than expected."],"answer":"A","explanation":"The text explicitly identifies both food and community benefits.","source":{"title":"Original practice passage","paragraphs":["A community garden added twelve plots to an unused lot. After one season, nearby residents reported that the garden provided fresh produce and also created a place to meet neighbors."]}},{"id":"RWM1Q2","section":"Reading and Writing","domain":"Craft and Structure","skill":"Words in context","difficulty":"easy","prompt":"As used in the text, “unexpected” most nearly means","options":["Unforeseen","Unwelcome","Temporary","Unimportant"],"answer":"A","explanation":"The director did not anticipate the high attendance.","source":{"title":"Original practice passage","paragraphs":["When the museum opened, its director called the small exhibit an “unexpected success,” noting that attendance had exceeded projections."]}},{"id":"RWM1Q3","section":"Reading and Writing","domain":"Expression of Ideas","skill":"Transitions","difficulty":"easy","prompt":"The city planted shade trees along several sidewalks. ___, summer surveys found that pedestrians were more likely to walk on those routes.","options":["In contrast","As a result","For example","Meanwhile"],"answer":"B","explanation":"The survey finding is presented as a consequence of planting the trees.","source":{"title":"Original practice passage","paragraphs":["The passage presents a situation that illustrates the relationship described in the question: The city planted shade trees along several sidewalks. ___, summer surveys found that pedestrians were more likely to walk on those routes."]}},{"id":"RWM1Q4","section":"Reading and Writing","domain":"Standard English Conventions","skill":"Subject-verb agreement","difficulty":"easy","prompt":"The collection of field notes from the expedition ___ in the university archive.","options":["are stored","were stored","is stored","have been stored"],"answer":"C","explanation":"The singular subject “collection” takes “is.”","source":{"title":"Original practice passage","paragraphs":["The passage presents a situation that illustrates the relationship described in the question: The collection of field notes from the expedition ___ in the university archive."]}},{"id":"RWM1Q5","section":"Reading and Writing","domain":"Information and Ideas","skill":"Quantitative evidence","difficulty":"easy","prompt":"How much greater was Group B's average than Group A's?","options":["1.3 hours","1.7 hours","7.7 hours","8.1 hours"],"answer":"A","explanation":"Subtracting 3.2 from 4.5 gives 1.3 hours.","source":{"title":"Original practice passage","paragraphs":["A study compared the average daily screen time of two groups. Group A averaged 3.2 hours; Group B averaged 4.5 hours."]}},{"id":"RWM1Q6","section":"Reading and Writing","domain":"Craft and Structure","skill":"Text structure and purpose","difficulty":"easy","prompt":"Why does the author present the study after describing the assumption?","options":["To challenge a belief with evidence","To provide a historical timeline","To introduce a competing species","To summarize the study's methods"],"answer":"A","explanation":"The study is used to complicate the initial assumption.","source":{"title":"Original practice passage","paragraphs":["The author first describes a common assumption about urban bees, then presents a study that complicates that assumption."]}},{"id":"RWM1Q7","section":"Reading and Writing","domain":"Standard English Conventions","skill":"Punctuation","difficulty":"easy","prompt":"The researchers tested three materials ___ cork, bamboo, and recycled foam.","options":["materials, cork","materials: cork","materials; cork","materials cork"],"answer":"B","explanation":"A colon properly introduces a list after a complete clause.","source":{"title":"Original practice passage","paragraphs":["The passage presents a situation that illustrates the relationship described in the question: The researchers tested three materials ___ cork, bamboo, and recycled foam."]}},{"id":"RWM1Q8","section":"Reading and Writing","domain":"Expression of Ideas","skill":"Rhetorical synthesis","difficulty":"easy","prompt":"Which choice most effectively uses the notes to introduce the program?","options":["The library offers free Saturday coding workshops for teens.","The library is one of several buildings downtown.","Many coding programs meet during the week.","Teens often visit libraries for many reasons."],"answer":"A","explanation":"It includes all three relevant notes directly.","source":{"title":"Original practice passage","paragraphs":["A student has notes about a local library program: it offers free coding workshops, meets every Saturday, and is open to teens."]}},{"id":"RWM1Q9","section":"Reading and Writing","domain":"Information and Ideas","skill":"Inference","difficulty":"medium","prompt":"What can reasonably be inferred?","options":["The revised procedure improved consistency.","The first trial proved the hypothesis false.","The researchers abandoned the experiment.","The second trial used fewer measurements."],"answer":"A","explanation":"The text connects the procedural revision with more consistent results.","source":{"title":"Original practice passage","paragraphs":["Although the first trial produced uneven results, the researchers revised the measurement procedure before repeating the experiment. The second trial produced much more consistent data."]}},{"id":"RWM1Q10","section":"Reading and Writing","domain":"Craft and Structure","skill":"Cross-text connections","difficulty":"medium","prompt":"How would the authors most likely respond to each other?","options":["They would disagree about the primary benefit of rooftop farms.","They would both reject rooftop farming.","They would agree that transportation is irrelevant.","They would agree that education is the only benefit."],"answer":"A","explanation":"The texts emphasize different primary benefits.","source":{"title":"Original practice passage","paragraphs":["Text 1 argues that rooftop farms can reduce the distance food travels. Text 2 argues that rooftop farms are valuable mainly because they create educational spaces."]}},{"id":"RWM1Q11","section":"Reading and Writing","domain":"Standard English Conventions","skill":"Verb tense","difficulty":"medium","prompt":"By the time the committee met in June, the volunteers ___ the survey responses for three weeks.","options":["review","have reviewed","had reviewed","will review"],"answer":"C","explanation":"Past perfect shows an action completed before another past event.","source":{"title":"Original practice passage","paragraphs":["The passage presents a situation that illustrates the relationship described in the question: By the time the committee met in June, the volunteers ___ the survey responses for three weeks."]}},{"id":"RWM1Q12","section":"Reading and Writing","domain":"Expression of Ideas","skill":"Transitions","difficulty":"medium","prompt":"The first prototype was inexpensive to build. ___, it used a material that could not withstand heat.","options":["Therefore","However","For instance","Similarly"],"answer":"B","explanation":"The second sentence contrasts with the first.","source":{"title":"Original practice passage","paragraphs":["The passage presents a situation that illustrates the relationship described in the question: The first prototype was inexpensive to build. ___, it used a material that could not withstand heat."]}},{"id":"RWM1Q13","section":"Reading and Writing","domain":"Information and Ideas","skill":"Command of evidence","difficulty":"medium","prompt":"Which finding best supports the claim that the restoration benefited bird habitat?","options":["Nesting species increased from 18 to 27.","The project lasted two years.","The wetland covered 40 acres.","Workers planted native grasses."],"answer":"A","explanation":"The increase in nesting species is direct evidence of improved habitat.","source":{"title":"Original practice passage","paragraphs":["A report notes that a wetland restoration project increased the number of nesting birds from 18 species to 27 species in two years."]}},{"id":"RWM1Q14","section":"Reading and Writing","domain":"Craft and Structure","skill":"Words in context","difficulty":"medium","prompt":"As used in the text, “restrained” most nearly means","options":["Measured","Confused","Enthusiastic","Incomplete"],"answer":"A","explanation":"The account avoids exaggerated praise and stays measured.","source":{"title":"Original practice passage","paragraphs":["The historian's account is notably restrained: rather than praising the leader, it lists the policy's measurable effects."]}},{"id":"RWM1Q15","section":"Reading and Writing","domain":"Standard English Conventions","skill":"Sentence boundaries","difficulty":"medium","prompt":"The telescope was difficult to transport ___ once assembled, it produced unusually clear images.","options":["transport, once","transport; once","transport once","transport: once"],"answer":"B","explanation":"A semicolon properly separates the two independent clauses.","source":{"title":"Original practice passage","paragraphs":["The passage presents a situation that illustrates the relationship described in the question: The telescope was difficult to transport ___ once assembled, it produced unusually clear images."]}},{"id":"RWM1Q16","section":"Reading and Writing","domain":"Information and Ideas","skill":"Central ideas","difficulty":"medium","prompt":"Which choice best states the main idea?","options":["The trees' growth pattern changed as their roots developed.","The trees stopped growing after three years.","Deep soil always causes rapid growth.","Researchers studied only mature trees."],"answer":"A","explanation":"The text emphasizes a change linked to root development.","source":{"title":"Original practice passage","paragraphs":["Researchers found that the tree species grew slowly during the first three years but then showed sharply increased growth after their roots reached deeper soil."]}},{"id":"RWM1Q17","section":"Reading and Writing","domain":"Expression of Ideas","skill":"Rhetorical synthesis","difficulty":"medium","prompt":"Which choice best introduces the piece using the notes?","options":["The 2024 piece draws on bird recordings and birdlike rhythms.","The composer has written many orchestral works.","Bird recordings can be difficult to collect.","The premiere attracted several musicians."],"answer":"A","explanation":"The sentence combines the most relevant notes.","source":{"title":"Original practice passage","paragraphs":["A student has notes: a composer studied field recordings of birds; she incorporated birdlike rhythms into a new orchestral piece; the piece premiered in 2024."]}},{"id":"RWM1Q18","section":"Reading and Writing","domain":"Craft and Structure","skill":"Text structure and purpose","difficulty":"medium","prompt":"What is the primary function of the middle portion?","options":["To contrast two approaches to reporting","To list the movement's founders","To define a technical term","To evaluate a single article"],"answer":"A","explanation":"The middle section establishes the contrast.","source":{"title":"Original practice passage","paragraphs":["The passage opens with a definition of “slow journalism,” then contrasts it with rapid online reporting before describing the movement's goals."]}},{"id":"RWM1Q19","section":"Reading and Writing","domain":"Standard English Conventions","skill":"Pronoun agreement","difficulty":"medium","prompt":"Each of the interns submitted ___ report before leaving for the day.","options":["their","they're","them","its"],"answer":"A","explanation":"Singular “they” agrees with “each” without changing the meaning.","source":{"title":"Original practice passage","paragraphs":["The passage presents a situation that illustrates the relationship described in the question: Each of the interns submitted ___ report before leaving for the day."]}},{"id":"RWM1Q20","section":"Reading and Writing","domain":"Information and Ideas","skill":"Quantitative evidence","difficulty":"medium","prompt":"Which month had the second-highest rainfall?","options":["January","February","March","April"],"answer":"C","explanation":"The values rank February first and March second.","source":{"title":"Original practice passage","paragraphs":["A chart shows monthly rainfall of 42 mm, 58 mm, 51 mm, and 49 mm from January through April."]}},{"id":"RWM1Q21","section":"Reading and Writing","domain":"Craft and Structure","skill":"Words in context","difficulty":"hard","prompt":"As used in the text, “provisional” most nearly means","options":["Tentative","Secretive","Permanent","Controversial"],"answer":"A","explanation":"The policy is presented as temporary or subject to revision.","source":{"title":"Original practice passage","paragraphs":["The author calls the policy “provisional,” emphasizing that officials expect to revise it after collecting more data."]}},{"id":"RWM1Q22","section":"Reading and Writing","domain":"Information and Ideas","skill":"Inference","difficulty":"hard","prompt":"Which inference is best supported?","options":["Reminders may be especially useful for borrowers with a history of late returns.","Reminders eliminate all late returns.","Participants disliked the reminders.","Only frequent borrowers responded."],"answer":"A","explanation":"The largest effect occurred in the previously late-returning group.","source":{"title":"Original practice passage","paragraphs":["A survey found that participants who received brief reminders were slightly more likely to return library books on time. The difference was greatest among participants who had previously returned books late."]}},{"id":"RWM1Q23","section":"Reading and Writing","domain":"Expression of Ideas","skill":"Transitions","difficulty":"hard","prompt":"The two batteries were similar in size and weight. ___, one stored nearly twice as much energy as the other.","options":["Nevertheless","Likewise","For example","In addition"],"answer":"A","explanation":"The sentence highlights a surprising contrast.","source":{"title":"Original practice passage","paragraphs":["The passage presents a situation that illustrates the relationship described in the question: The two batteries were similar in size and weight. ___, one stored nearly twice as much energy as the other."]}},{"id":"RWM1Q24","section":"Reading and Writing","domain":"Standard English Conventions","skill":"Punctuation","difficulty":"hard","prompt":"The survey included one open-ended question ___ participants could explain their reasoning in their own words.","options":["question, in which","question; in which","question in which","question: in which"],"answer":"C","explanation":"No punctuation is needed before the restrictive relative clause.","source":{"title":"Original practice passage","paragraphs":["The passage presents a situation that illustrates the relationship described in the question: The survey included one open-ended question ___ participants could explain their reasoning in their own words."]}},{"id":"RWM1Q25","section":"Reading and Writing","domain":"Craft and Structure","skill":"Cross-text connections","difficulty":"hard","prompt":"Which choice best describes the relationship between the texts?","options":["Text 2 adds a potential drawback to Text 1's positive view.","Text 2 rejects the existence of public murals.","Text 1 focuses only on economic effects.","The texts make identical claims about redevelopment."],"answer":"A","explanation":"Text 2 accepts a benefit while adding a complication.","source":{"title":"Original practice passage","paragraphs":["Text 1 argues that public murals can strengthen neighborhood identity. Text 2 agrees but warns that murals can also accelerate redevelopment and displacement."]}},{"id":"RWM1Q26","section":"Reading and Writing","domain":"Information and Ideas","skill":"Command of evidence","difficulty":"hard","prompt":"Which conclusion is best supported by the results?","options":["Moderate shade may balance water retention with growth.","Full sun is always best for plants.","Heavy shade increases growth rate.","Water retention has no relation to light."],"answer":"A","explanation":"The results show a trade-off and a middle condition.","source":{"title":"Original practice passage","paragraphs":["In an experiment, plants exposed to moderate shade retained more water than plants in full sun, while plants in heavy shade grew less quickly."]}},{"id":"RWM1Q27","section":"Reading and Writing","domain":"Expression of Ideas","skill":"Rhetorical synthesis","difficulty":"hard","prompt":"Which choice most effectively presents the significance of the bridge?","options":["Its steel-truss design enabled longer spans and influenced later bridge construction.","The bridge was built in 1890 in a growing city.","Engineers used stone before steel became common.","Other cities had bridges of many different designs."],"answer":"A","explanation":"The choice connects the structural innovation with its influence.","source":{"title":"Original practice passage","paragraphs":["Notes: the 1890 bridge used steel trusses; its design allowed a longer span than earlier stone bridges; engineers copied the design in other cities."]}}],"rw2":{"easy":[],"hard":[{"id":"RWM2HQ1","section":"Reading and Writing","domain":"Craft and Structure","skill":"Words in context","difficulty":"hard","prompt":"As used in the text, “equivocal” most nearly means","options":["ambiguous","exhaustive","predictable","irrelevant"],"answer":"A","explanation":"The ending allows multiple interpretations, so it is ambiguous.","source":{"title":"Original practice passage","paragraphs":["The critic describes the novel's ending as “deliberately equivocal,” because the final scene supports more than one plausible interpretation."]}},{"id":"RWM2HQ2","section":"Reading and Writing","domain":"Information and Ideas","skill":"Inference","difficulty":"hard","prompt":"Which inference is best supported?","options":["The new schedule may improve water efficiency.","The new schedule always increases yield.","The older schedule requires no irrigation.","The farmers stopped growing crops."],"answer":"A","explanation":"Using less water for a similar yield suggests greater efficiency.","source":{"title":"Original practice passage","paragraphs":["After a drought year, farmers who adopted the new irrigation schedule used less water while maintaining nearly the same crop yield as farmers using the older schedule."]}},{"id":"RWM2HQ3","section":"Reading and Writing","domain":"Expression of Ideas","skill":"Transitions","difficulty":"hard","prompt":"The first survey measured attitudes immediately after the workshop. ___, the researchers conducted a second survey six months later to see whether the change lasted.","options":["In addition","By contrast","For instance","As a result"],"answer":"A","explanation":"The second survey is an additional step.","source":{"title":"Original practice passage","paragraphs":["The first survey measured attitudes immediately after the workshop. ___, the researchers conducted a second survey six months later to see whether the change lasted."]}},{"id":"RWM2HQ4","section":"Reading and Writing","domain":"Standard English Conventions","skill":"Agreement","difficulty":"hard","prompt":"Neither the collection of maps nor the field journals ___ available for public viewing yet.","options":["is","are","was","has been"],"answer":"B","explanation":"With “neither...nor,” the verb agrees with the nearer plural subject, “journals.”","source":{"title":"Original practice passage","paragraphs":["The passage presents a situation that illustrates the relationship described in the question: Neither the collection of maps nor the field journals ___ available for public viewing yet."]}},{"id":"RWM2HQ5","section":"Reading and Writing","domain":"Information and Ideas","skill":"Quantitative evidence","difficulty":"hard","prompt":"Which claim is best supported by the graph?","options":["Capacity declines as charge cycles increase.","Capacity rises after 200 cycles.","The battery loses exactly 11% each time.","The battery reaches zero capacity at 400 cycles."],"answer":"A","explanation":"Every later measurement is lower than the previous one.","source":{"title":"Original practice passage","paragraphs":["A graph shows that a battery retained 92%, 81%, 74%, and 68% of its original capacity after 100, 200, 300, and 400 charge cycles."]}},{"id":"RWM2HQ6","section":"Reading and Writing","domain":"Craft and Structure","skill":"Text structure and purpose","difficulty":"hard","prompt":"Why does the author evaluate the explanations after presenting them?","options":["To compare their evidentiary strength","To introduce a third migration pattern","To define migration","To summarize unrelated research"],"answer":"A","explanation":"The evaluation helps readers compare the explanations.","source":{"title":"Original practice passage","paragraphs":["The author presents two explanations for a migration pattern and then evaluates the evidence supporting each explanation."]}},{"id":"RWM2HQ7","section":"Reading and Writing","domain":"Standard English Conventions","skill":"Punctuation","difficulty":"hard","prompt":"The committee's recommendation was concise ___ it nevertheless addressed every major concern raised during the hearing.","options":["concise, but","concise; but","concise but;","concise: but"],"answer":"A","explanation":"A comma and coordinating conjunction join the independent clauses.","source":{"title":"Original practice passage","paragraphs":["The passage presents a situation that illustrates the relationship described in the question: The committee's recommendation was concise ___ it nevertheless addressed every major concern raised during the hearing."]}},{"id":"RWM2HQ8","section":"Reading and Writing","domain":"Expression of Ideas","skill":"Rhetorical synthesis","difficulty":"hard","prompt":"Which choice best emphasizes the archive's new usefulness to researchers?","options":["Digitized photographs with searchable captions can be located by date and place.","The archive contains many photographs from different years.","Volunteers contributed time to the digitization project.","Researchers sometimes visit archives to study images."],"answer":"A","explanation":"It directly connects digitization and captions to searchable access.","source":{"title":"Original practice passage","paragraphs":["Notes: the archive digitized 12,000 photographs; volunteers added searchable captions; researchers can now locate images by date and place."]}},{"id":"RWM2HQ9","section":"Reading and Writing","domain":"Information and Ideas","skill":"Central ideas","difficulty":"hard","prompt":"Which choice best states the central idea?","options":["Results became more realistic when the experiment included relevant environmental factors.","The first phase was more accurate than the second.","Field observations are too complex to study experimentally.","The authors rejected controlled experiments."],"answer":"A","explanation":"The contrast between phases supports this conclusion.","source":{"title":"Original practice passage","paragraphs":["The experiment's first phase isolated one variable, while the second phase introduced several realistic environmental factors. The authors report that the second phase produced results closer to field observations."]}},{"id":"RWM2HQ10","section":"Reading and Writing","domain":"Craft and Structure","skill":"Cross-text connections","difficulty":"hard","prompt":"How does Text 2 qualify Text 1?","options":["It adds an environmental cost to an otherwise positive assessment.","It disputes that buses produce emissions.","It argues that batteries cannot be recycled.","It changes the topic from transportation to agriculture."],"answer":"A","explanation":"Text 2 adds a cost without rejecting the main benefit.","source":{"title":"Original practice passage","paragraphs":["Text 1 argues that electric buses can lower urban emissions. Text 2 agrees but notes that manufacturing batteries also has environmental costs."]}},{"id":"RWM2HQ11","section":"Reading and Writing","domain":"Standard English Conventions","skill":"Verb tense","difficulty":"hard","prompt":"By the time the article appeared in print, the researchers ___ their findings at three conferences.","options":["present","presented","had presented","will present"],"answer":"C","explanation":"Past perfect indicates earlier completed presentations.","source":{"title":"Original practice passage","paragraphs":["The passage presents a situation that illustrates the relationship described in the question: By the time the article appeared in print, the researchers ___ their findings at three conferences."]}},{"id":"RWM2HQ12","section":"Reading and Writing","domain":"Expression of Ideas","skill":"Transitions","difficulty":"hard","prompt":"The device can detect very small changes in temperature. ___, it is too fragile for use in the field without protective housing.","options":["Therefore","However","Similarly","For example"],"answer":"B","explanation":"The second sentence limits the practical usefulness of the first.","source":{"title":"Original practice passage","paragraphs":["The passage presents a situation that illustrates the relationship described in the question: The device can detect very small changes in temperature. ___, it is too fragile for use in the field without protective housing."]}},{"id":"RWM2HQ13","section":"Reading and Writing","domain":"Information and Ideas","skill":"Command of evidence","difficulty":"hard","prompt":"Which result most directly supports the claim that the new lanes encouraged cycling?","options":["Bicycle traffic rose 41%.","Automobile traffic changed by less than 2%.","Two intersections were studied.","The comparison used before-and-after data."],"answer":"A","explanation":"The large increase in bicycle traffic is direct evidence.","source":{"title":"Original practice passage","paragraphs":["A city compared two intersections before and after adding protected bike lanes. Bicycle traffic rose 41%, while automobile traffic changed by less than 2%."]}},{"id":"RWM2HQ14","section":"Reading and Writing","domain":"Craft and Structure","skill":"Words in context","difficulty":"hard","prompt":"As used in the text, “cautious” most nearly means","options":["careful","dismissive","celebratory","impatient"],"answer":"A","explanation":"The author avoids a strong conclusion and stresses further evidence.","source":{"title":"Original practice passage","paragraphs":["The report's tone is “cautious”: it describes the preliminary result as promising but emphasizes the need for a larger sample."]}},{"id":"RWM2HQ15","section":"Reading and Writing","domain":"Standard English Conventions","skill":"Sentence boundaries","difficulty":"hard","prompt":"The river rose rapidly overnight ___ by morning, several roads were closed.","options":["overnight, by","overnight; by","overnight by","overnight: by"],"answer":"B","explanation":"Two independent clauses are joined with a semicolon.","source":{"title":"Original practice passage","paragraphs":["The passage presents a situation that illustrates the relationship described in the question: The river rose rapidly overnight ___ by morning, several roads were closed."]}},{"id":"RWM2HQ16","section":"Reading and Writing","domain":"Information and Ideas","skill":"Inference","difficulty":"hard","prompt":"Which statement is most appropriate?","options":["The timing of feedback may be associated with revision, but motivation could also matter.","Fast feedback proves that every student revises more.","Motivation had no effect on the study.","Late feedback causes students to stop writing."],"answer":"A","explanation":"The uncontrolled motivation variable limits a causal conclusion.","source":{"title":"Original practice passage","paragraphs":["Students who received feedback within 24 hours revised their essays more often than students who received feedback after one week. The study did not control for how motivated the students were."]}},{"id":"RWM2HQ17","section":"Reading and Writing","domain":"Expression of Ideas","skill":"Rhetorical synthesis","difficulty":"hard","prompt":"Which choice most effectively highlights the catalog's lasting contribution?","options":["Chen's multi-observatory catalog of 1,800 variable stars later helped researchers identify unusual stellar behavior.","Chen worked with three observatories while studying stars.","Variable stars can change brightness over time.","Researchers often compare observations from different observatories."],"answer":"A","explanation":"It connects the scale and method of the catalog to its later use.","source":{"title":"Original practice passage","paragraphs":["Notes: astronomer Lina Chen cataloged 1,800 variable stars; her catalog included measurements from three observatories; later researchers used it to identify unusual stellar behavior."]}},{"id":"RWM2HQ18","section":"Reading and Writing","domain":"Craft and Structure","skill":"Text structure and purpose","difficulty":"hard","prompt":"What is the primary function of the measurements?","options":["To challenge the initial explanation with direct evidence","To define sediment","To describe a second lake","To explain how water is filtered"],"answer":"A","explanation":"The measurements contradict the opening explanation.","source":{"title":"Original practice passage","paragraphs":["The passage begins with a common explanation for why a lake became clearer, then introduces sediment measurements that contradict that explanation."]}},{"id":"RWM2HQ19","section":"Reading and Writing","domain":"Standard English Conventions","skill":"Punctuation","difficulty":"hard","prompt":"The researchers tracked three variables ___ temperature, humidity, and soil moisture ___ at hourly intervals.","options":["variables: temperature, humidity, and soil moisture","variables; temperature, humidity, and soil moisture","variables, temperature, humidity, and soil moisture","variables temperature, humidity, and soil moisture"],"answer":"A","explanation":"A colon appropriately introduces the list.","source":{"title":"Original practice passage","paragraphs":["The passage presents a situation that illustrates the relationship described in the question: The researchers tracked three variables ___ temperature, humidity, and soil moisture ___ at hourly intervals."]}},{"id":"RWM2HQ20","section":"Reading and Writing","domain":"Information and Ideas","skill":"Quantitative evidence","difficulty":"hard","prompt":"What percentage of residents were undecided?","options":["15%","20%","25%","35%"],"answer":"A","explanation":"There are 36 undecided residents; 36 ÷ 240 = 15%.","source":{"title":"Original practice passage","paragraphs":["A survey of 240 residents found that 156 supported the proposed transit line, 48 opposed it, and the remainder were undecided."]}},{"id":"RWM2HQ21","section":"Reading and Writing","domain":"Craft and Structure","skill":"Cross-text connections","difficulty":"hard","prompt":"Which statement best synthesizes the texts?","options":["Community science can expand data collection, especially when experts provide consistent methods.","Community science should replace professional researchers.","Experts should collect all data themselves.","Volunteer observations are always unreliable."],"answer":"A","explanation":"Both texts support participation while emphasizing the importance of sound methods.","source":{"title":"Original practice passage","paragraphs":["Text 1 presents community science as a way to expand data collection. Text 2 argues that volunteer observations are most valuable when experts establish clear protocols."]}},{"id":"RWM2HQ22","section":"Reading and Writing","domain":"Expression of Ideas","skill":"Transitions","difficulty":"hard","prompt":"The historical record is incomplete. ___, letters preserved in family archives offer details unavailable in official reports.","options":["Nevertheless","Consequently","Likewise","For example"],"answer":"A","explanation":"Despite the incomplete record, the letters provide useful details.","source":{"title":"Original practice passage","paragraphs":["The passage presents a situation that illustrates the relationship described in the question: The historical record is incomplete. ___, letters preserved in family archives offer details unavailable in official reports."]}},{"id":"RWM2HQ23","section":"Reading and Writing","domain":"Standard English Conventions","skill":"Pronoun reference","difficulty":"hard","prompt":"The committee reviewed the proposal and its budget before publishing ___ recommendations.","options":["their","its","it's","they're"],"answer":"B","explanation":"“Committee” is singular in formal agreement here, so “its” refers to the committee.","source":{"title":"Original practice passage","paragraphs":["The passage presents a situation that illustrates the relationship described in the question: The committee reviewed the proposal and its budget before publishing ___ recommendations."]}},{"id":"RWM2HQ24","section":"Reading and Writing","domain":"Information and Ideas","skill":"Central ideas","difficulty":"hard","prompt":"Which choice best describes the finding?","options":["The material's strength depended on both drying and subsequent heating.","Drying always weakened the material.","Heating had no measurable effect.","The researchers confirmed their original expectation."],"answer":"A","explanation":"The strongest result occurred only when heating followed drying.","source":{"title":"Original practice passage","paragraphs":["At first, the researchers expected the material to become stronger when dried. Instead, strength increased only after a brief heating stage followed the drying process."]}},{"id":"RWM2HQ25","section":"Reading and Writing","domain":"Craft and Structure","skill":"Words in context","difficulty":"hard","prompt":"As used in the text, “anomaly” most nearly means","options":["unexpected observation","confirmed prediction","routine measurement","published conclusion"],"answer":"A","explanation":"An anomaly is an observation that does not fit the expected pattern.","source":{"title":"Original practice passage","paragraphs":["The biologist treats the apparent anomaly as “informative,” since it exposes a limitation in the model rather than simply representing error."]}},{"id":"RWM2HQ26","section":"Reading and Writing","domain":"Expression of Ideas","skill":"Rhetorical synthesis","difficulty":"hard","prompt":"Which choice best explains how the theater restored the marquee?","options":["Using archival photographs, the theater recreated the marquee's original 1920s color scheme.","The theater reopened its doors after a renovation.","Archival photographs can preserve historical details.","The marquee is one of the building's most visible features."],"answer":"A","explanation":"It incorporates the method and result from the notes.","source":{"title":"Original practice passage","paragraphs":["Notes: a theater restored its 1920s marquee; the restoration used archival photographs; the marquee now matches the building's original color scheme."]}},{"id":"RWM2HQ27","section":"Reading and Writing","domain":"Standard English Conventions","skill":"Verb form","difficulty":"hard","prompt":"The editor requested that every quotation ___ checked against the original recording.","options":["is","be","was","will be"],"answer":"B","explanation":"The mandative subjunctive takes “be checked.”","source":{"title":"Original practice passage","paragraphs":["The passage presents a situation that illustrates the relationship described in the question: The editor requested that every quotation ___ checked against the original recording."]}}]},"math1":[{"id":"MM1Q1","section":"Math","domain":"Algebra","skill":"Linear equations in one variable","difficulty":"easy","prompt":"A student buys 3 notebooks for $3.50 each and a calculator case for $11.50. A $3.00 coupon is applied to the total. What is the final cost?","type":"mcq","options":["$17.00","$19.00","$21.00","$23.00"],"answer":"B","explanation":"The original total is 3(3.50)+11.50=$22.00. Subtracting the $3.00 coupon gives $19.00."},{"id":"MM1Q2","section":"Math","domain":"Algebra","skill":"Linear functions","difficulty":"easy","prompt":"A line is represented by y = 2x − 7. What is the value of y when x = 6?","type":"mcq","options":["3","5","7","9"],"answer":"B","explanation":"Substituting x=6 gives y=12−7=5."},{"id":"MM1Q3","section":"Math","domain":"Algebra","skill":"Systems of equations","difficulty":"easy","prompt":"The system 2x + y = 19 and x − y = 2 has solution (x, y). What is the value of y?","type":"mcq","options":["4","5","6","8"],"answer":"B","explanation":"Adding the equations gives 3x=21, so x=7. Then y=5."},{"id":"MM1Q4","section":"Math","domain":"Algebra","skill":"Linear inequalities in one variable","difficulty":"easy","prompt":"The inequality 5x − 8 < 17 is satisfied by all values less than 5. What is the greatest integer x that satisfies the inequality?","type":"spr","options":[],"answer":"4","explanation":"Adding 8 and dividing by 5 gives x<5, so the greatest integer solution is 4."},{"id":"MM1Q5","section":"Math","domain":"Algebra","skill":"Linear equations in context","difficulty":"medium","prompt":"A school club charges a one-time $12 fee plus $3.50 for each workshop attended. If a student pays $47 in total, how many workshops did the student attend?","type":"mcq","options":["8","9","10","11"],"answer":"C","explanation":"The equation 12+3.50w=47 gives 3.50w=35, so w=10."},{"id":"MM1Q6","section":"Math","domain":"Algebra","skill":"Linear functions","difficulty":"medium","prompt":"A line passes through (4, 9) and (10, 24). What is the value of y when x = 16?","type":"mcq","options":["35","37","39","41"],"answer":"C","explanation":"The slope is (24−9)/(10−4)=5/2. Using (4,9) gives y=(5/2)x−1. At x=16, y=39."},{"id":"MM1Q7","section":"Math","domain":"Algebra","skill":"Systems of equations in context","difficulty":"medium","prompt":"A theater sold 84 tickets. Adult tickets cost $9 each and student tickets cost $6 each. If the theater collected $666, how many adult tickets were sold?","type":"spr","options":[],"answer":"54","explanation":"Let a be adult tickets. Then a+s=84 and 9a+6s=666. Substitution gives 3a=162, so a=54."},{"id":"MM1Q8","section":"Math","domain":"Advanced Math","skill":"Equivalent expressions","difficulty":"easy","prompt":"Which expression is equivalent to (x + 4)^2 − 9?","type":"mcq","options":["x^2+4x+7","x^2+8x+7","x^2+8x−7","x^2+16x+7"],"answer":"B","explanation":"Expanding gives x^2+8x+16−9=x^2+8x+7."},{"id":"MM1Q9","section":"Math","domain":"Advanced Math","skill":"Quadratic equations","difficulty":"easy","prompt":"The solutions of x^2 + 2x − 15 = 0 are 3 and −5. What is the sum of the two solutions?","type":"mcq","options":["−8","−2","2","8"],"answer":"B","explanation":"The roots are 3 and −5, whose sum is −2."},{"id":"MM1Q10","section":"Math","domain":"Advanced Math","skill":"Exponential functions","difficulty":"medium","prompt":"A laboratory culture starts with 800 cells and decreases by 15% each hour. According to the model 800(0.85)^t, how many cells are predicted after 2 hours?","type":"mcq","options":["520","560","578","680"],"answer":"C","explanation":"After two hours the model gives 800(0.85)^2=800(0.7225)=578."},{"id":"MM1Q11","section":"Math","domain":"Advanced Math","skill":"Nonlinear functions","difficulty":"medium","prompt":"Let f(x)=3x^2−4x+1. What is f(2)?","type":"mcq","options":["1","5","8","10"],"answer":"B","explanation":"f(2)=3(4)−8+1=5."},{"id":"MM1Q12","section":"Math","domain":"Advanced Math","skill":"Quadratic equations with parameters","difficulty":"hard","prompt":"The equation x^2 + kx + 12 = 0 has 3 as one of its solutions. What is the value of k?","type":"spr","options":[],"answer":"-7","explanation":"Substituting x=3 gives 9+3k+12=0, so 3k=−21 and k=−7."},{"id":"MM1Q13","section":"Math","domain":"Advanced Math","skill":"Radical equations","difficulty":"hard","prompt":"For x ≥ 1, √(x + 5) = x − 1. What is the value of x?","type":"mcq","options":["2","3","4","5"],"answer":"C","explanation":"Squaring gives x+5=(x−1)^2, so x^2−3x−4=0. The solutions are 4 and −1; only 4 satisfies x≥1."},{"id":"MM1Q14","section":"Math","domain":"Advanced Math","skill":"Rational equations","difficulty":"hard","prompt":"For x ≠ 1, the equation 4/(x − 1) = 2 is true. What is x?","type":"mcq","options":["1","2","3","5"],"answer":"C","explanation":"Multiplying by x−1 gives 4=2x−2, so x=3."},{"id":"MM1Q15","section":"Math","domain":"Problem Solving and Data Analysis","skill":"Ratios, rates, proportional relationships, and units","difficulty":"easy","prompt":"A sports drink is mixed with water in a ratio of 2 parts concentrate to 5 parts water. If the mixture contains 42 liters in total, how many liters are concentrate?","type":"mcq","options":["10","12","14","16"],"answer":"B","explanation":"There are 7 total parts, so each part is 6 liters. Two parts give 12 liters."},{"id":"MM1Q16","section":"Math","domain":"Problem Solving and Data Analysis","skill":"Percentages","difficulty":"easy","prompt":"A town had 240 trees in a park. After a restoration project, the number increased to 276. What was the percent increase?","type":"mcq","options":["12%","14%","15%","18%"],"answer":"C","explanation":"The increase is 36, and 36/240=0.15, or 15%."},{"id":"MM1Q17","section":"Math","domain":"Problem Solving and Data Analysis","skill":"Two-variable data: models","difficulty":"medium","prompt":"A model for the number of visitors to a museum is y = 4.2x + 18, where x is the number of advertising spots purchased. According to the model, how much does y increase when x increases by 5?","type":"mcq","options":["17","19","21","23"],"answer":"C","explanation":"The slope 4.2 represents the predicted increase for one additional spot. Five spots give 4.2×5=21."},{"id":"MM1Q18","section":"Math","domain":"Problem Solving and Data Analysis","skill":"Probability and conditional probability","difficulty":"hard","prompt":"A bag contains 5 blue marbles and 3 red marbles. Two marbles are selected without replacement. What is the probability that both selected marbles are blue?","type":"spr","options":[],"answer":"5/14","explanation":"The probability is (5/8)(4/7)=20/56=5/14."},{"id":"MM1Q19","section":"Math","domain":"Geometry and Trigonometry","skill":"Lines, angles, and triangles","difficulty":"easy","prompt":"The angles of a triangle measure 2x°, 3x°, and 4x°. What is the measure of the largest angle?","type":"mcq","options":["60°","70°","80°","90°"],"answer":"C","explanation":"The angles sum to 180°, so 9x=180 and x=20. The largest angle is 4x=80°."},{"id":"MM1Q20","section":"Math","domain":"Geometry and Trigonometry","skill":"Area and volume","difficulty":"medium","prompt":"A trapezoid has parallel sides of lengths 10 and 16 and a height of 7. What is the area of the trapezoid?","type":"mcq","options":["84","91","98","105"],"answer":"B","explanation":"The area is (1/2)(10+16)(7)=91."},{"id":"MM1Q21","section":"Math","domain":"Geometry and Trigonometry","skill":"Circles","difficulty":"medium","prompt":"A circle has circumference 18π. What is its area, in terms of π?","type":"mcq","options":["36π","72π","81π","162π"],"answer":"C","explanation":"The circumference is 2πr=18π, so r=9. The area is 81π."},{"id":"MM1Q22","section":"Math","domain":"Geometry and Trigonometry","skill":"Right triangles and trigonometry","difficulty":"hard","prompt":"A right triangle has legs of lengths 7 and 24. Relative to the angle opposite the side of length 7, what is the value of sin θ?","type":"spr","options":[],"answer":"7/25","explanation":"The hypotenuse is 25 by the Pythagorean theorem. Thus sin θ=opposite/hypotenuse=7/25."}],"math2":{"easy":[{"id":"MM2EQ1","section":"Math","domain":"Algebra","skill":"Linear equations in one variable","difficulty":"easy","prompt":"A store marks down a jacket by $18. The sale price is $42. What was the original price of the jacket?","type":"spr","options":[],"answer":"60","explanation":"Let p be the original price. p−18=42, so p=60."},{"id":"MM2EQ2","section":"Math","domain":"Algebra","skill":"Linear functions","difficulty":"easy","prompt":"A line is represented by y = −3x + 11. For what value of x is y = −4?","type":"mcq","options":["1","5","9","13"],"answer":"B","explanation":"Substituting y=−4 gives −4=−3x+11, so x=5."},{"id":"MM2EQ3","section":"Math","domain":"Algebra","skill":"Systems of equations","difficulty":"easy","prompt":"The system 2x + y = 14 and x − y = 1 has solution (x, y). What is x?","type":"mcq","options":["3","4","5","6"],"answer":"C","explanation":"Adding the equations gives 3x=15, so x=5."},{"id":"MM2EQ4","section":"Math","domain":"Algebra","skill":"Linear inequalities in one variable","difficulty":"easy","prompt":"The inequality 3x + 4 ≥ 19 describes the number of hours h a machine must operate. What is the least integer number of hours that satisfies the inequality?","type":"spr","options":[],"answer":"5","explanation":"Subtract 4 and divide by 3 to get x≥5, so the least integer is 5."},{"id":"MM2EQ5","section":"Math","domain":"Algebra","skill":"Linear equations in context","difficulty":"medium","prompt":"A taxi charges a $4.50 starting fee plus $1.75 for each mile. If a ride costs $18.50, how many miles were traveled?","type":"mcq","options":["6","7","8","9"],"answer":"C","explanation":"The equation 4.50+1.75m=18.50 gives 1.75m=14, so m=8."},{"id":"MM2EQ6","section":"Math","domain":"Algebra","skill":"Linear functions","difficulty":"medium","prompt":"A line passes through (0, −2) and (6, 10). What is the slope of the line?","type":"mcq","options":["0","1","2","5"],"answer":"C","explanation":"The slope is (10−(−2))/(6−0)=2."},{"id":"MM2EQ7","section":"Math","domain":"Algebra","skill":"Linear equations in context","difficulty":"medium","prompt":"A printer charges a setup fee of $8 plus $5.25 for each poster. If the total charge is $50, how many posters were printed?","type":"mcq","options":["7","8","9","10"],"answer":"B","explanation":"The equation 8+5.25n=50 gives 5.25n=42, so n=8."},{"id":"MM2EQ8","section":"Math","domain":"Advanced Math","skill":"Quadratic equations","difficulty":"easy","prompt":"One solution of x^2 − 9x + 20 = 0 is 4. What is the other solution?","type":"mcq","options":["3","5","6","7"],"answer":"B","explanation":"The polynomial factors as (x−4)(x−5), so the other solution is 5."},{"id":"MM2EQ9","section":"Math","domain":"Advanced Math","skill":"Exponential equations","difficulty":"easy","prompt":"If 2^(x+3) = 64, what is the value of x?","type":"mcq","options":["2","3","4","6"],"answer":"B","explanation":"Since 64=2^6, x+3=6 and x=3."},{"id":"MM2EQ10","section":"Math","domain":"Advanced Math","skill":"Nonlinear functions","difficulty":"medium","prompt":"Let f(x)=x^2+3x. What is f(−4)?","type":"mcq","options":["−4","0","4","8"],"answer":"C","explanation":"f(−4)=16−12=4."},{"id":"MM2EQ11","section":"Math","domain":"Advanced Math","skill":"Equivalent expressions","difficulty":"medium","prompt":"Which expression is equivalent to 3(2x − 5) − 2(x + 1)?","type":"mcq","options":["2x−17","4x−17","4x−13","8x−7"],"answer":"B","explanation":"Distributing gives 6x−15−2x−2=4x−17."},{"id":"MM2EQ12","section":"Math","domain":"Advanced Math","skill":"Quadratic equations with parameters","difficulty":"medium","prompt":"The equation x^2 − 6x + k = 0 has 2 as one of its solutions. What is k?","type":"spr","options":[],"answer":"8","explanation":"Substituting x=2 gives 4−12+k=0, so k=8."},{"id":"MM2EQ13","section":"Math","domain":"Advanced Math","skill":"Radical equations","difficulty":"medium","prompt":"If √(x + 1) = 5, what is x?","type":"mcq","options":["20","24","25","26"],"answer":"B","explanation":"Squaring both sides gives x+1=25, so x=24."},{"id":"MM2EQ14","section":"Math","domain":"Problem Solving and Data Analysis","skill":"Ratios, rates, proportional relationships, and units","difficulty":"easy","prompt":"A car travels 360 miles using 8 gallons of fuel. At the same rate, how many miles does the car travel per gallon?","type":"mcq","options":["36","40","45","48"],"answer":"C","explanation":"The unit rate is 360/8=45 miles per gallon."},{"id":"MM2EQ15","section":"Math","domain":"Problem Solving and Data Analysis","skill":"Percentages","difficulty":"easy","prompt":"A $75 backpack is discounted by 18%. What is the sale price?","type":"mcq","options":["$57.50","$61.50","$63.50","$66.50"],"answer":"B","explanation":"The discount is 0.18×75=$13.50, so the sale price is $61.50."},{"id":"MM2EQ16","section":"Math","domain":"Problem Solving and Data Analysis","skill":"One-variable data: measures of center","difficulty":"medium","prompt":"The five values 4, 8, 8, 10, and 15 represent the number of books read by five students. What is the mean?","type":"mcq","options":["7","8","9","12"],"answer":"B","explanation":"The sum is 45, and 45/5=9."},{"id":"MM2EQ17","section":"Math","domain":"Problem Solving and Data Analysis","skill":"Probability and conditional probability","difficulty":"medium","prompt":"A class has 20 students, and 8 of them prefer tea to coffee. If a student is selected at random, what is the probability that the student prefers tea?","type":"spr","options":[],"answer":"2/5","explanation":"The probability is 8/20, which simplifies to 2/5."},{"id":"MM2EQ18","section":"Math","domain":"Geometry and Trigonometry","skill":"Area and volume","difficulty":"easy","prompt":"A triangle has a base of 14 centimeters and a height of 9 centimeters. What is its area?","type":"mcq","options":["56","63","72","126"],"answer":"B","explanation":"The area is (1/2)(14)(9)=63 cm²."},{"id":"MM2EQ19","section":"Math","domain":"Geometry and Trigonometry","skill":"Circles","difficulty":"medium","prompt":"A circle has radius 6. What is its area, in terms of π?","type":"mcq","options":["12π","18π","24π","36π"],"answer":"D","explanation":"The area is πr²=36π."},{"id":"MM2EQ20","section":"Math","domain":"Geometry and Trigonometry","skill":"Lines, angles, and triangles","difficulty":"medium","prompt":"Two parallel lines are cut by a transversal. One pair of alternate interior angles measures (x+25)° and (3x−15)°. What is the measure of either angle?","type":"mcq","options":["35°","45°","55°","65°"],"answer":"B","explanation":"Alternate interior angles are equal, so x+25=3x−15. This gives x=20 and the angle is 45°."},{"id":"MM2EQ21","section":"Math","domain":"Geometry and Trigonometry","skill":"Area and similarity","difficulty":"medium","prompt":"Two similar rectangles have corresponding side lengths in the ratio 2:3. If the smaller rectangle has area 40 square units, what is the area of the larger rectangle?","type":"mcq","options":["60","72","90","120"],"answer":"C","explanation":"Areas scale by the square of the side ratio: 40(3/2)^2=40(9/4)=90 square units."},{"id":"MM2EQ22","section":"Math","domain":"Advanced Math","skill":"Quadratic equations","difficulty":"hard","prompt":"If (x − 4)^2 = 25 and x > 4, what is the value of x?","type":"spr","options":[],"answer":"9","explanation":"Taking the square root gives x−4=±5. Since x>4, x−4=5 and x=9."}],"hard":[{"id":"MM2HQ1","section":"Math","domain":"Algebra","skill":"Systems of equations in context","difficulty":"hard","prompt":"A theater sells adult tickets for $16 and student tickets for $11. One performance sells 96 tickets for $1,306. How many adult tickets are sold?","type":"mcq","options":["44","48","50","52"],"answer":"C","explanation":"Let a be adult tickets. Then a+s=96 and 16a+11s=1306. Substitution gives 5a=250, so a=50."},{"id":"MM2HQ2","section":"Math","domain":"Algebra","skill":"Linear functions","difficulty":"hard","prompt":"A line passes through (3,10) and (9,28). According to the line, what is the value of y when x = −4?","type":"mcq","options":["−17","−11","−5","11"],"answer":"B","explanation":"The slope is 3 and the equation is y=3x+1. At x=−4, y=−11."},{"id":"MM2HQ3","section":"Math","domain":"Algebra","skill":"Systems of equations with parameters","difficulty":"hard","prompt":"The system 2x + 3y = 17 and 4x + ky = 34 represents the same line. What is the value of k?","type":"spr","options":[],"answer":"6","explanation":"The second equation must be exactly twice the first, so k=6."},{"id":"MM2HQ4","section":"Math","domain":"Algebra","skill":"Linear inequalities in context","difficulty":"hard","prompt":"A delivery service charges a fixed $37 fee plus $4.75 for each package. A customer can spend at most $100. What is the greatest number of complete packages the customer can send?","type":"mcq","options":["11","12","13","14"],"answer":"C","explanation":"The inequality 37+4.75n≤100 gives n≤13.26..., so the greatest whole number is 13."},{"id":"MM2HQ5","section":"Math","domain":"Algebra","skill":"Linear functions","difficulty":"hard","prompt":"A linear model passes through the points (−2,9), (1,3), and (4,−3). What is the y-intercept of the model?","type":"mcq","options":["2","4","5","7"],"answer":"C","explanation":"The slope is −2. Using (1,3), y=−2x+5, so the y-intercept is 5."},{"id":"MM2HQ6","section":"Math","domain":"Algebra","skill":"Systems of equations in context","difficulty":"hard","prompt":"A school sold 72 tickets to a play. Adult tickets cost $14 and student tickets cost $9. If the school collected $843, how many adult tickets were sold?","type":"mcq","options":["33","36","39","42"],"answer":"C","explanation":"Let a be adult tickets. Then 14a+9(72−a)=843, which gives 5a=195 and a=39."},{"id":"MM2HQ7","section":"Math","domain":"Algebra","skill":"Linear equations in two variables","difficulty":"hard","prompt":"The line 3x − 2y = 8 is perpendicular to another line. What is the slope of the perpendicular line?","type":"mcq","options":["−3/2","−2/3","2/3","3/2"],"answer":"B","explanation":"Writing the equation as y=(3/2)x−4 shows the original slope is 3/2. A perpendicular line has slope −2/3."},{"id":"MM2HQ8","section":"Math","domain":"Advanced Math","skill":"Quadratic functions","difficulty":"hard","prompt":"For the quadratic y = x^2 − 12x + 20, what is the x-coordinate of the vertex?","type":"mcq","options":["4","5","6","7"],"answer":"C","explanation":"For ax²+bx+c, the vertex x-coordinate is −b/(2a)=12/2=6."},{"id":"MM2HQ9","section":"Math","domain":"Advanced Math","skill":"Exponential equations","difficulty":"hard","prompt":"If 5^(x+1) = 125^(x−1), what is x?","type":"mcq","options":["1","2","3","5"],"answer":"B","explanation":"Since 125=5^3, the exponents satisfy x+1=3x−3, giving x=2."},{"id":"MM2HQ10","section":"Math","domain":"Advanced Math","skill":"Absolute-value equations","difficulty":"hard","prompt":"The equation |3x−5|=13 has two solutions. What is the greater solution?","type":"spr","options":[],"answer":"6","explanation":"The two cases are 3x−5=13 and 3x−5=−13, giving x=6 and x=−8/3. The greater solution is 6."},{"id":"MM2HQ11","section":"Math","domain":"Advanced Math","skill":"Polynomial equations","difficulty":"hard","prompt":"The equation (x−2)^2(x+3)=0 has distinct real solutions 2 and −3. What is the sum of the distinct real solutions?","type":"mcq","options":["−5","−1","1","5"],"answer":"B","explanation":"The distinct solutions are 2 and −3, so their sum is −1."},{"id":"MM2HQ12","section":"Math","domain":"Advanced Math","skill":"Rational equations","difficulty":"hard","prompt":"For x ≠ −1 and x ≠ 1, the equation 2/(x+1) + 1/(x−1) = 1 has two solutions. What is the sum of the solutions?","type":"mcq","options":["0","2","3","5"],"answer":"C","explanation":"Multiplying by (x+1)(x−1) gives 2x−2+x+1=x²−1, so x²−3x=0. The solutions are 0 and 3, whose sum is 3."},{"id":"MM2HQ13","section":"Math","domain":"Advanced Math","skill":"Function composition","difficulty":"hard","prompt":"Let f(x)=2x−1 and g(x)=x^2+4. What is g(f(2))?","type":"mcq","options":["9","11","13","15"],"answer":"C","explanation":"f(2)=3, and g(3)=3²+4=13."},{"id":"MM2HQ14","section":"Math","domain":"Advanced Math","skill":"Radical equations","difficulty":"hard","prompt":"For x ≥ 2, √(x + 4) = x − 2. What is the value of x?","type":"spr","options":[],"answer":"5","explanation":"Squaring gives x+4=(x−2)^2, which simplifies to x(x−5)=0. The condition x≥2 leaves x=5."},{"id":"MM2HQ15","section":"Math","domain":"Problem Solving and Data Analysis","skill":"Inference from sample statistics and margin of error","difficulty":"hard","prompt":"A random sample estimates that 47% of students at a school prefer a new schedule. The reported margin of error is 3 percentage points. Which interval represents the estimate plus or minus the margin of error?","type":"mcq","options":["42% to 52%","44% to 50%","45% to 49%","46% to 48%"],"answer":"B","explanation":"Subtracting and adding 3 percentage points to 47% gives 44% to 50%."},{"id":"MM2HQ16","section":"Math","domain":"Problem Solving and Data Analysis","skill":"Inference from sample statistics","difficulty":"hard","prompt":"A random sample of 800 customers finds that 18% used a store's mobile app during a visit. Based on the sample proportion, how many of the store's 800 customers would be expected to use the app?","type":"mcq","options":["108","126","144","162"],"answer":"C","explanation":"0.18×800=144."},{"id":"MM2HQ17","section":"Math","domain":"Problem Solving and Data Analysis","skill":"Two-variable data: models","difficulty":"hard","prompt":"For a data point, a linear model predicts a value of 57 while the observed value is 61. What is the residual for this data point?","type":"mcq","options":["−4","0","4","118"],"answer":"C","explanation":"Residual = observed − predicted = 61−57=4."},{"id":"MM2HQ18","section":"Math","domain":"Problem Solving and Data Analysis","skill":"Probability and conditional probability","difficulty":"hard","prompt":"In a group, 7 boys and 5 girls are enrolled in an instrument class. Of the boys, 3 play an instrument outside class; of the girls, 2 do. If a student known to play an instrument outside class is selected at random, what is the probability the student is a boy?","type":"spr","options":[],"answer":"3/5","explanation":"There are 5 students who play an instrument outside class, 3 of whom are boys, so the conditional probability is 3/5."},{"id":"MM2HQ19","section":"Math","domain":"Geometry and Trigonometry","skill":"Circles","difficulty":"hard","prompt":"A circle has radius 13. A chord is 5 units from the center of the circle. What is the length of the chord?","type":"mcq","options":["10","12","24","26"],"answer":"C","explanation":"The perpendicular from the center bisects the chord. A right triangle has hypotenuse 13 and one leg 5, so the half-chord is 12. The full chord is 24."},{"id":"MM2HQ20","section":"Math","domain":"Geometry and Trigonometry","skill":"Area and similarity","difficulty":"hard","prompt":"Two similar figures have corresponding side lengths in the ratio 5:7. If the smaller figure has area 100 square units, what is the area of the larger figure?","type":"mcq","options":["140","169","196","245"],"answer":"C","explanation":"Area scales by (7/5)^2=49/25. Thus 100×49/25=196."},{"id":"MM2HQ21","section":"Math","domain":"Geometry and Trigonometry","skill":"Area and volume","difficulty":"hard","prompt":"A cylinder has radius 6 and height 9. A cone has the same radius and height. What is the volume of the cone, in terms of π?","type":"mcq","options":["54π","108π","162π","324π"],"answer":"B","explanation":"The cone volume is (1/3)πr²h=(1/3)π(36)(9)=108π."},{"id":"MM2HQ22","section":"Math","domain":"Geometry and Trigonometry","skill":"Right triangles and trigonometry","difficulty":"hard","prompt":"In a right triangle, tan θ = 3/4 and the hypotenuse is 20. What is the length of the side opposite θ?","type":"spr","options":[],"answer":"12","explanation":"A 3-4-5 triangle scaled by 4 has opposite side 12 and hypotenuse 20."}]}};window.SAT_QUESTIONS.rw2.easy=window.SAT_QUESTIONS.rw1.map((q,i)=>({...q,id:`RWM2EQ${i+1}`}));window.SAT_QUESTIONS.math2.easy=window.SAT_QUESTIONS.math2.easy.map(q=>q);